   '{"en":{"subject":"Your payment promise","body":"We registered your promise to pay {{promise.amount}} by {{promise.dueAt}}. Collection is paused until then."},"nb":{"subject":"Betalingsavtalen din","body":"Vi har registrert at du betaler {{promise.amount}} innen {{promise.dueAt}}. Innkreving er satt pa pause til da."}}',
